.img-popup-trigger {
    display: inline-block;
    cursor: pointer;
    text-decoration: none;
    line-height: 0;
  }
  .img-thumb-wrap {
    position: relative;
    display: inline-block;
    max-width: 800px;
    border-radius: .3rem;
    overflow: hidden;
    transition: transform 0.25s ease;
  }
  .img-popup-trigger:hover .img-thumb-wrap {
    transform: scale(1.03);
  }
  .img-thumb-wrap figure {
    margin: 0;
    display: block;
  }
  .img-thumb-wrap figure img {
    display: block;
    width: 100%;
    height: auto;
    border-radius: .3rem;
  }
  .img-expand-overlay {
    position: absolute;
    inset: 0;
    display: flex;
    justify-content: center;
    align-items: center;
    background: rgba(0,0,0,0.35);
    opacity: 0;
    transition: opacity 0.25s ease;
    border-radius: .3rem;
    pointer-events: none;
    z-index: 2;
  }
  .img-popup-trigger:hover .img-expand-overlay {
    opacity: 1;
  }
  .img-expand-btn {
    background: rgba(0,0,0,0.6);
    color: #fff;
    border: 1px solid rgba(255,255,255,0.3);
    padding: 8px 12px;
    font-size: 0.9rem;
    border-radius: .3rem;
    backdrop-filter: blur(3px);
    line-height: 1.2;
  }
  .img-popup-modal {
    display: none;
    position: fixed !important;
    inset: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    background: rgba(0,0,0,0.7) !important;
    z-index: 2147483647 !important;
    justify-content: center !important;
    align-items: center !important;
    margin: 0 !important;

